messages.content:
[
 {
  "id": "A01",
  "step": "Answer a candidate's questions about a posted role",
  "kind": "read",
  "facts": "Answers come from the approved job posting and the benefits summary."
 },
 {
  "id": "A02",
  "step": "Draft a job advertisement from an approved requisition",
  "kind": "draft",
  "facts": "A recruiter edits and posts the advertisement."
 },
 {
  "id": "A03",
  "step": "Book interview slots for candidates a recruiter has advanced",
  "kind": "write",
  "facts": "Slots come from interviewer calendars; candidates can rebook online."
 },
 {
  "id": "A04",
  "step": "Decide which applicants advance to interview",
  "kind": "write",
  "facts": "Field roles in Colorado"
 },
 {
  "id": "A05",
  "step": "Reject an applicant and close the application",
  "kind": "write",
  "facts": "Applies in the US"
 },
 {
  "id": "A06",
  "step": "Send the outcome email after a recruiter has recorded a rejection with a reason code",
  "kind": "write",
  "facts": "The email uses an approved template; the decision is already recorded by a named recruiter."
 },
 {
  "id": "A07",
  "step": "Make a job offer and send the offer letter",
  "kind": "write",
  "facts": "Start date"
 },
 {
  "id": "A08",
  "step": "Withdraw a job offer",
  "kind": "write",
  "facts": "Most withdrawals follow a background-check result or a failed right-to-work check."
 },
 {
  "id": "B01",
  "step": "Mark a right-to-work file complete or incomplete",
  "kind": "write",
  "facts": "The checklist names each required document and its validity dates; an incomplete file goes to an HR adviser."
 },
 {
  "id": "B02",
  "step": "Decide that a new hire cannot start because right-to-work evidence failed verification",
  "kind": "write",
  "facts": "UK"
 },
 {
  "id": "B03",
  "step": "Order equipment and system accounts for a confirmed new hire",
  "kind": "write",
  "facts": "Role-based bundles; orders can be cancelled the same day."
 },
 {
  "id": "B04",
  "step": "Enroll a new hire in the onboarding courses their role requires",
  "kind": "write",
  "facts": "The course list per role is published by the learning team."
 },
 {
  "id": "B05",
  "step": "Answer a new hire's questions about policies and first-week logistics",
  "kind": "read",
  "facts": "Answers cite the policy library and the onboarding pack."
 },
 {
  "id": "B06",
  "step": "Order a background check from the vendor after the candidate accepts and signs the consent form",
  "kind": "write",
  "facts": "US and UK roles; the check cannot be recalled once the vendor starts it."
 },
 {
  "id": "B07",
  "step": "Decide what to do about an adverse background-check result",
  "kind": "write",
  "facts": "US roles under fair-chance rules; results can include criminal records."
 },
 {
  "id": "B08",
  "step": "Set the probation review date in the HRIS from the contract type",
  "kind": "write",
  "facts": "Contract types and probation lengths are fixed in policy."
 }
]

[
 {
  "id": "C01",
  "step": "Answer an employee's questions about their payslip",
  "kind": "read",
  "facts": "Answers cite the payslip lines and the pay policy."
 },
 {
  "id": "C02",
  "step": "Apply the annual increase set by the collective agreement to covered employees",
  "kind": "write",
  "facts": "The agreement's pay table sets every rate; the change is loaded before the payroll cutoff and can be corrected before pay day."
 },
 {
  "id": "C03",
  "step": "Set pay for a promotion inside the band",
  "kind": "write",
  "facts": "Managers choose a point in the band using experience and market data."
 },
 {
  "id": "C04",
  "step": "Approve pay outside the band",
  "kind": "write",
  "facts": "Exceptions create a precedent other employees can cite."
 },
 {
  "id": "C05",
  "step": "Change an employee's bank details at their request",
  "kind": "write",
  "facts": "The request comes through the employee portal; a payment to a wrong account cannot be recalled."
 },
 {
  "id": "C06",
  "step": "Recover an overpayment by deduction from wages",
  "kind": "write",
  "facts": "US"
 },
 {
  "id": "C07",
  "step": "Flag a timesheet with hours more than two above the scheduled shift for manager review",
  "kind": "write",
  "facts": "The flag holds the timesheet in a queue; nothing is paid or cut."
 },
 {
  "id": "C08",
  "step": "Calculate overtime pay from approved timesheets",
  "kind": "write",
  "facts": "Rates come from the agreement and state law tables; payroll can correct before pay day."
 },
 {
  "id": "D01",
  "step": "Answer questions about leave balances and leave policy",
  "kind": "read",
  "facts": "Balances come from the HRIS."
 },
 {
  "id": "D02",
  "step": "Book annual leave the employee requested within their balance on dates the team cover rule allows",
  "kind": "write",
  "facts": "The employee can cancel the booking in the portal."
 },
 {
  "id": "D03",
  "step": "Refuse or move an employee's leave request",
  "kind": "write",
  "facts": "Managers weigh cover"
 },
 {
  "id": "D04",
  "step": "Decide whether an employee is eligible for family or medical leave",
  "kind": "write",
  "facts": "US FMLA and state leave laws; UK and Australian statutory leave; medical certification may be involved."
 },
 {
  "id": "D05",
  "step": "Enroll an employee in the benefit options they selected during open enrollment",
  "kind": "write",
  "facts": "Elections can be changed until the window closes."
 },
 {
  "id": "D06",
  "step": "Decide a request for a reasonable accommodation or adjustment",
  "kind": "write",
  "facts": "Requests usually involve a disability or health condition."
 },
 {
  "id": "D07",
  "step": "Remind employees who have not enrolled before the benefits window closes",
  "kind": "write",
  "facts": "Reminders use an approved message."
 },
 {
  "id": "D08",
  "step": "Pay sick pay on a claim backed by a medical certificate that meets the policy rule",
  "kind": "write",
  "facts": "The rule sets eligibility and rate; payroll can correct before pay day."
 }
]

[
 {
  "id": "E01",
  "step": "Draft next week's roster from availability and the agreement's scheduling rules",
  "kind": "draft",
  "facts": "A scheduler reviews"
 },
 {
  "id": "E02",
  "step": "Approve a shift swap between two qualified employees who both asked for it",
  "kind": "write",
  "facts": "Both employees confirm in the app; qualification data comes from the HRIS."
 },
 {
  "id": "E03",
  "step": "Offer an open shift to employees on the voluntary overtime list in agreement order",
  "kind": "write",
  "facts": "The agreement sets the order; the offer can be withdrawn before the shift is accepted."
 },
 {
  "id": "E04",
  "step": "Require an employee to work mandatory overtime",
  "kind": "write",
  "facts": "Union agreements in Illinois"
 },
 {
  "id": "E05",
  "step": "Record attendance from badge data",
  "kind": "write",
  "facts": "Employees can see and dispute their records in the app."
 },
 {
  "id": "E06",
  "step": "Issue an attendance warning when absence points pass the threshold",
  "kind": "write",
  "facts": "Points accrue under a written policy; warnings stay on file and are steps in the disciplinary procedure."
 },
 {
  "id": "E07",
  "step": "Remind an employee to complete a missing timesheet",
  "kind": "write",
  "facts": "Reminders use an approved message."
 },
 {
  "id": "E08",
  "step": "Change an employee's contracted hours",
  "kind": "write",
  "facts": "Contracts and agreements set notice and consent requirements."
 },
 {
  "id": "F01",
  "step": "Suggest learning courses to an employee from their skills profile",
  "kind": "draft",
  "facts": "The employee chooses whether to enroll."
 },
 {
  "id": "F02",
  "step": "Summarize a year of check-in notes for the manager writing the annual review",
  "kind": "draft",
  "facts": "The manager reads the source notes and writes the review."
 },
 {
  "id": "F03",
  "step": "Set an employee's annual performance rating",
  "kind": "write",
  "facts": "Ratings feed pay increases and promotion eligibility."
 },
 {
  "id": "F04",
  "step": "Decide a promotion",
  "kind": "write",
  "facts": "Candidates are compared across a level."
 },
 {
  "id": "F05",
  "step": "Choose which employees are shown an internal vacancy based on their skills profile",
  "kind": "write",
  "facts": "Employees not shown the vacancy may not learn of it; matching rules are published."
 },
 {
  "id": "F06",
  "step": "Enroll an employee in the compliance training their role requires",
  "kind": "write",
  "facts": "The required list per role is set by the compliance team."
 },
 {
  "id": "F07",
  "step": "Place an employee on a performance improvement plan",
  "kind": "write",
  "facts": "The plan is a formal stage before capability or conduct proceedings."
 },
 {
  "id": "F08",
  "step": "Approve tuition reimbursement within the policy limit",
  "kind": "write",
  "facts": "The policy lists eligible courses and the annual cap; payment runs with payroll."
 }
]

[
 {
  "id": "G01",
  "step": "Log a grievance and acknowledge receipt with the procedure timeline",
  "kind": "write",
  "facts": "The acknowledgment uses the timeline from the grievance procedure."
 },
 {
  "id": "G02",
  "step": "Route a harassment report to the investigations team",
  "kind": "write",
  "facts": "Routing rules exclude anyone named in the report."
 },
 {
  "id": "G03",
  "step": "Decide the outcome of a disciplinary hearing",
  "kind": "write",
  "facts": "Union agreements and the disciplinary procedure apply."
 },
 {
  "id": "G04",
  "step": "Make the findings of a workplace investigation",
  "kind": "write",
  "facts": "Findings can lead to discipline or dismissal."
 },
 {
  "id": "G05",
  "step": "Summarize investigation interview notes for the investigator",
  "kind": "draft",
  "facts": "The investigator reads every source note before making findings."
 },
 {
  "id": "G06",
  "step": "Suspend an employee pending an investigation",
  "kind": "write",
  "facts": "Suspension is on full pay; it affects reputation and access to the workplace."
 },
 {
  "id": "G07",
  "step": "Answer a manager's question about the disciplinary procedure",
  "kind": "read",
  "facts": "Answers cite the procedure and the relevant agreement."
 },
 {
  "id": "G08",
  "step": "Send a disciplinary hearing notice with the right to be accompanied after a manager has decided to hold the hearing",
  "kind": "write",
  "facts": "Notice periods come from the procedure and union agreements."
 },
 {
  "id": "H01",
  "step": "Update an employee's home address at their request",
  "kind": "write",
  "facts": "The employee confirms the change in the portal and can change it again."
 },
 {
  "id": "H02",
  "step": "Send an employment verification letter to a lender at the employee's request",
  "kind": "write",
  "facts": "Standard fields only; once sent"
 },
 {
  "id": "H03",
  "step": "Answer questions about the employee handbook",
  "kind": "read",
  "facts": "Answers cite the handbook section."
 },
 {
  "id": "H04",
  "step": "Dismiss an employee",
  "kind": "write",
  "facts": "Applies across all Hartwell countries."
 },
 {
  "id": "H05",
  "step": "Select employees for redundancy or layoff",
  "kind": "write",
  "facts": "Selection pools and criteria are consulted on; age and disability risks are reviewed."
 },
 {
  "id": "H06",
  "step": "Process a resignation the employee submitted and start the exit checklist",
  "kind": "write",
  "facts": "The employee can withdraw the resignation within the notice period by agreement."
 },
 {
  "id": "H07",
  "step": "Calculate final pay from the system of record",
  "kind": "write",
  "facts": "Accrued leave and final pay rules come from policy and state law; payroll reviews before payment."
 },
 {
  "id": "H08",
  "step": "Remove system access on the recorded termination date",
  "kind": "write",
  "facts": "Access can be restored the same day if the date was wrong."
 }
]
